pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        // No prior state needed; call getFirstWithdrawalBonus directly
        bool ok;
        try c.getFirstWithdrawalBonus(alice) { ok = true; } catch { ok = false; }
        // In the reference, getFirstWithdrawalBonus succeeds (calls withdrawReward which succeeds) and sets claimedBonus[alice] = true
