pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(address(c), 0); // ensure contract starts with 0
        vm.deal(alice, 0);
        vm.prank(alice);
        // This call will revert on reference (transfer fails for 100 wei) but succeed on mutant (transfer does nothing)
        bool ok;
        try c.getFirstWithdrawalBonus(alice) { ok = true; } catch { ok = false; }
        // In reference P, call reverts so ok is false, contract balance remains 0.
        // In mutant M, call succeeds so ok is true, contract balance remains 0 because no ether was sent.
        // As specified, P.withdrawReward() != M.withdrawReward()? Actually the difference stated: after call, 'withdrawReward' state variable differs.
        // The C contract has no state variable named withdrawReward; the difference description uses 'withdrawReward' loosely.
        // Our concrete divergence: in P, getFirstWithdrawalBonus always reverts (no bonus given), in M it doesn't revert.
        // So assertTrue that the call reverted (ok == false) which holds for reference and fails for mutant.
        assertTrue(ok == false);
    }
}

