pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Reentrant contract that calls getFirstWithdrawalBonus again in receive()
        address reentrant = address(new Reentrant(address(c)));
        // Fund the C contract with 200 wei
        vm.deal(address(c), 200);
        // Start prank as the reentrant contract
        vm.prank(reentrant);
        c.getFirstWithdrawalBonus(reentrant);
        // After the call, in reference reentrant call succeeds -> both 100 withdrawn -> balance 0
        // In buggy, reentrant call fails -> only first withdrawal -> balance 100
        assertTrue(address(c).balance < 150, "Balance should be 0 (reference) or 100 (buggy)");
    }
}

contract Reentrant {
    C c;
    bool entered = false;
    constructor(address _c) { c = C(_c); }
    receive() external payable {
        if (!entered) {
            entered = true;
            c.getFirstWithdrawalBonus(address(this));
        }
    }
}

